```json
{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, min(value) AS min_val, max(value) AS max_val, count(*) AS n, min(time) AS t0, max(time) AS t1 FROM abnormal_metrics WHERE metric = 'k8s.deployment.available' AND service_name IN ('profile','frontend','search','mongodb-profile') GROUP BY ALL ORDER BY service_name",
          "claim": "profile deployment reports 0 available pods from 15:25:35 onward; other deployments stay at 1."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' AS period, count(*) AS profile_spans FROM abnormal_traces WHERE service_name = 'profile' UNION ALL SELECT 'normal', count(*) FROM normal_traces WHERE service_name = 'profile'",
          "claim": "profile emits no spans in the abnormal window, versus about 3,790 spans in the normal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) AS client_calls, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE span_name = 'profile.Profile/GetProfiles' AND attr_span_kind = 'Client'",
          "claim": "Every frontend client call to profile.Profile/GetProfiles errors in the abnormal window (all calls failed)."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, message, count(*) AS n FROM abnormal_logs WHERE level = 'ERROR' GROUP BY ALL",
          "claim": "frontend logs 393 'Get profiles failed' errors in the abnormal window, and no other service logs errors."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS m, count(*) AS calls, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE span_name = 'profile.Profile/GetProfiles' AND attr_span_kind = 'Client' GROUP BY ALL ORDER BY m",
          "claim": "Frontend's calls to profile fail every minute from 15:26 onward, and frontend's user-facing requests then error."
        }
      ]
    }
  ]
}
```

